Think: Normalize paths and resolve symlink targets, appending unresolved link notices to errors.log and writing normalized records to temp_var_inventory/normalized_listing.txt.

Act: bash

```bash
awk -F '\t' '{
  path=$1; type=$2; target=$3;
  resolved="";
  cmd="realpath -e \"" path "\" 2>/dev/null";
  if((cmd | getline resolved) > 0) { close(cmd) } else { close(cmd); resolved="" }
  if(type=="l" && resolved=="") {
    print "Unresolved symlink: " path " -> " target >> "temp_var_inventory/errors.log"
  }
  if(resolved=="") {
    cmd2="realpath -m \"" path "\" 2>/dev/null";
    if((cmd2 | getline resolved) > 0) close(cmd2); else close(cmd2)
  }
  print resolved "\t" type "\t" target >> "temp_var_inventory/normalized_listing.txt"
}' temp_var_inventory/raw_listing.txt
```

