Think: Create normalized_listing.txt by resolving each path from raw_listing.txt with realpath, logging unresolved symlinks to errors.log.

Act: bash

```bash
awk -F '\t' '{
  path=$1; type=$2; target=$3;
  resolved="";
  cmd = "realpath -e \"" path "\" 2>/dev/null";
  if ((cmd | getline resolved) <= 0) { close(cmd); resolved=""; } else close(cmd);
  if (type=="l" && resolved=="") {
    print "Unresolved symlink: " path " -> " target >> "temp_var_inventory/errors.log"
  }
  if (resolved=="") {
    cmd2 = "realpath -m \"" path "\" 2>/dev/null";
    if ((cmd2 | getline resolved) <= 0) close(cmd2); else close(cmd2);
  }
  print resolved "\t" type "\t" target
}' temp_var_inventory/raw_listing.txt > temp_var_inventory/normalized_listing.txt
